        assertNull(urlBuilder.q);
    }

    @Test
    public void decodePart() throws UnsupportedEncodingException {
        String encoded = "þäöü";
        String expectedDecoded = "thaeo%FCue";
        assertEquals(expectedDecoded, UrlBuilder.decodePart(encoded));
    }
