        assertEquals("http://example.com", builder.build().toString());
    }

    @Test
    public void testBuildUrlWithQuery() throws Exception {
        URL url = new URL("http://example.com?query=abc&def=ghi");
        UrlBuilder builder = new UrlBuilder(url);
        String expectedQueryString = "query1=" + URLEncoder.encode("abc", "UTF-8") + "&def=" + URLEncoder.encode("ghi", "UTF-8");
        assertEquals(expectedQueryString, builder.build().getQuery());
    }

    @Test
    public void testBuildUrlWithQueryAndFragment() throws Exception {
        URL url = new URL("http://example.com#fragment");
        UrlBuilder builder = new UrlBuilder(url);
        String expectedQueryString = "";
        assertEquals(expectedQueryString, builder.build().getQuery());
    }
}

public class UrlBuilder {

    private URL url;
    private URI parsedUrl;

    public UrlBuilder(URL url) {
        this.url = url;
        this.parsedUrl = url.toURI();
    }

    public String build() throws UnsupportedEncodingException {
        StringBuilder sb = new StringBuilder();
        if (parsedUrl.getQuery() != null) {
            sb.append(parsedUrl.getScheme()).append("://").append(parsedUrl.getHost())
                .append("?query=").append(URLEncoder.encode(parsedUrl.getQuery(), "UTF-8"));
        }
        return sb.toString();
    }

    public String getQuery() throws UnsupportedEncodingException {
        if (parsedUrl.getQuery() != null) {
            return URLEncoder.encode(parsedUrl.getQuery(), "UTF-8");
        } else {
            return "";
        }
    }
}
